    },
    {
      "label": "Related link",
      "url": "https://dotesports.com/general/news/how-to-play-infinite-craft-from-neal-fun"
    },
    {
      "label": "Related link",
      "url": "https://play.google.com/store/apps/details?id=fun.neal.infinite.craft&hl=en"
    }
  ],
  "repository_created_at": null,
  "analysis": {
